feredReader(new InputStreamReader(System.in));\\n        // Read input and solve\\n    }\\n}", "rust": "use std::io::{self, BufRead};\\n\\nfn main() {\\n    let stdin = io::stdin();\\n    // Read input and solve\\n}", "python": "def main():\\n    import sys\\n    input_data = sys.stdin.read().split()\\n    if not input_data:\\n        return\\n    n = int(input_data[0])\\n    # Solve\\n    \\nif __name__ == \\"__main__\\":\\n    main()"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    int n;\\n    if (!(cin >> n)) return 0;\\n    long long max_val = -2e18;\\n    for (int i = 0; i < n; i++) {\\n        long long val;\\n        cin >> val;\\n        max_val = max(max_val, val);\\n    }\\n    cout << max_val << \\"\\\\n\\";\\n    return 0;\\n}", "java": "import java.io.*;\\nimport java.util.*;\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        String line1 = br.readLine();\\n        if (line1 == null) return;\\n        int n = Integer.parseInt(line1.trim());\\n        String line2 = br.readLine();\\n        if (line2 == null) return;\\n        StringTokenizer st = new StringTokenizer(line2);\\n        long maxVal = Long.MIN_VALUE;\\n        for (int i = 0; i < n; i++) {\\n            long val = Long.parseLong(st.nextToken());\\n            if (val > maxVal) {\\n                maxVal = val;\\n            }\\n        }\\n        System.out.println(maxVal);\\n    }\\n}", "rust": "use std::io::{self, BufRead, Write, BufWriter};\\nfn main() {\\n    let stdin = io::stdin();\\n    let stdout = io::stdout();\\n    let mut out = BufWriter::new(stdout.lock());\\n    let mut lines = stdin.lock().lines();\\n    if let Some(Ok(line1)) = lines.next() {\\n        let n: usize = line1.trim().parse().unwrap();\\n        if let Some(Ok(line2)) = lines.next() {\\n            let mut max_val = i64::MIN;\\n            for token in line2.split_whitespace() {\\n                let val: i64 = token.parse().unwrap();\\n                if val > max_val {\\n                    max_val = val;\\n                }\\n            }\\n            writeln!(out, \\"{}\\", max_val).unwrap();\\n        }\\n    }\\n}", "python": "import sys\\ndef main():\\n    input_data = sys.stdin.read().split()\\n    if not input_data:\\n        return\\n    n = int(input_data[0])\\n    arr = [int(x) for x in input_data[1:1+n]]\\n    print(max(arr))\\nif __name__ == '__main__':\\n    main()"}	2026-07-03 07:10:28.213	2026-07-03 07:10:28.213
5d998d0b-1b9d-4237-9a0e-efc6ae4d516e	Check Palindrome String	Given a string s, determine if it is a palindrome. A string is a palindrome if it reads the same backward as forward. The string will consist only of lowercase English letters.\n\n**Input Format:**\n- A single line containing the string s\n\n**Output Format:**\n- Print "true" if s is a palindrome, "false" otherwise	EASY	{strings}	ccf6772f-27d4-4001-bd5e-763e3c380ba0	[{"input": "racecar", "title": "Example 1", "output": "true", "explanation": "'racecar' reads the same forward and backward."}, {"input": "hello", "title": "Example 2", "output": "false", "explanation": "'hello' reversed is 'olleh', which is different."}]	1 <= s.length <= 10^5\ns consists only of lowercase English letters	Compare characters from both ends moving towards the center using two pointers.	**Approach: Two Pointers**\n\nInitialize `left = 0` and `right = s.length() - 1`. If `s[left] != s[right]`, return false. Increment left and decrement right until they meet. If all characters match, return true.\n\n**Time Complexity:** O(s.length())\n**Space Complexity:** O(1)	[{"input": "racecar", "output": "true"}, {"input": "hello", "output": "false"}, {"input": "a", "output": "true"}, {"input": "ab", "output": "false"}, {"input": "aba", "output": "true"}, {"input": "abba", "output": "true"}, {"input": "abcba", "output": "true"}, {"input": "abac", "output": "false"}, {"input": "xyzzyx", "output": "true"}, {"input": "abcdefgfedcba", "output": "true"}]	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    string s;\\n    if (cin >> s) {\\n        // Check palindrome\\n    }\\n    return 0;\\n}", "java": "import java.io.*;\\nimport java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        // Read input and solve\\n    }\\n}", "rust": "use std::io::{self, BufRead};\\n\\nfn main() {\\n    let stdin = io::stdin();\\n    // Read input and solve\\n}", "python": "def main():\\n    import sys\\n    s = sys.stdin.read().strip()\\n    # Solve\\n    \\nif __name__ == \\"__main__\\":\\n    main()"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    string s;\\n    if (!(cin >> s)) return 0;\\n    bool is_palindrome = true;\\n    int left = 0, right = (int)s.length() - 1;\\n    while (left < right) {\\n        if (s[left] != s[right]) {\\n            is_palindrome = false;\\n            break;\\n        }\\n        left++;\\n        right--;\\n    }\\n    cout << (is_palindrome ? \\"true\\" : \\"false\\") << \\"\\\\n\\";\\n    return 0;\\n}", "java": "import java.io.*;\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        String s = br.readLine();\\n        if (s == null) return;\\n        s = s.trim();\\n        boolean isPalindrome = true;\\n        int left = 0, right = s.length() - 1;\\n        while (left < right) {\\n            if (s.charAt(left) != s.charAt(right)) {\\n                isPalindrome = false;\\n                break;\\n            }\\n            left++;\\n            right--;\\n        }\\n        System.out.println(isPalindrome ? \\"true\\" : \\"false\\");\\n    }\\n}", "rust": "use std::io::{self, BufRead, Write, BufWriter};\\nfn main() {\\n    let stdin = io::stdin();\\n    let stdout = io::stdout();\\n    let mut out = BufWriter::new(stdout.lock());\\n    let mut lines = stdin.lock().lines();\\n    if let Some(Ok(line)) = lines.next() {\\n        let s = line.trim();\\n        let bytes = s.as_bytes();\\n        let mut is_palindrome = true;\\n        let mut left = 0;\\n        let mut right = bytes.len() as isize - 1;\\n        while left < right {\\n            if bytes[left as usize] != bytes[right as usize] {\\n                is_palindrome = false;\\n                break;\\n            }\\n            left += 1;\\n            right -= 1;\\n        }\\n        writeln!(out, \\"{}\\", if is_palindrome { \\"true\\" } else { \\"false\\" }).unwrap();\\n    }\\n}", "python": "import sys\\ndef main():\\n    s = sys.stdin.read().strip()\\n    if not s:\\n        return\\n    is_palindrome = s == s[::-1]\\n    print(\\"true\\" if is_palindrome else \\"false\\")\\nif __name__ == '__main__':\\n    main()"}	2026-07-03 07:10:28.214	2026-07-03 07:10:28.214
b6f67259-5699-4c24-8e5c-375dc1f55085	Longest Substring Without Repeating Characters	Given a string s, find the length of the longest substring without repeating characters.\n\n**Input Format:**\n- A single line containing the string s\n\n**Output Format:**\n- A single integer representing the length of the longest substring without repeating characters	MEDIUM	{strings,subarray}	ccf6772f-27d4-4001-bd5e-763e3c380ba0	[{"input": "abcabcbb", "title": "Example 1", "output": "3", "explanation": "The longest substring without repeating characters is 'abc', with length 3."}, {"input": "bbbbb", "title": "Example 2", "output": "1", "explanation": "The longest substring is 'b', with length 1."}]	0 <= s.length <= 10^5\ns consists of English letters, digits, symbols and spaces.	Use a sliding window or a two-pointer technique. Maintain the indices of characters in a hash map or direct access array to quickly jump the left pointer when a duplicate is found.	**Approach: Sliding Window**\n\nMaintain a sliding window `[start, i]`. For each character `c = s[i]`, if `c` has been seen within the current window (its stored index >= `start`), move `start` to `index + 1`. Update the last seen position of `c` to `i`, and compute the maximum length `i - start + 1`.\n\n**Time Complexity:** O(n)\n**Space Complexity:** O(min(m, n)) where m is the alphabet size.	[{"input": "abcabcbb", "output": "3"}, {"input": "bbbbb", "output": "1"}, {"input": "pwwkew", "output": "3"}, {"input": "a", "output": "1"}, {"input": "abcdefg", "output": "7"}, {"input": "aab", "output": "2"}, {"input": "dvdf", "output": "3"}, {"input": "tmmzuxt", "output": "5"}, {"input": "space space", "output": "6"}, {"input": "1234567890aBcd!", "output": "15"}]	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    string s;\\n    if (getline(cin, s)) {\\n        // Find longest substring without repeating chars\\n    }\\n    return 0;\\n}", "java": "import java.io.*;\\nimport java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        // Read input and solve\\n    }\\n}", "rust": "use std::io::{self, BufRead};\\n\\nfn main() {\\n    let stdin = io::stdin();\\n    // Read input and solve\\n}", "python": "def main():\\n    import sys\\n    # Solve\\n    \\nif __name__ == \\"__main__\\":\\n    main()"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    string s;\\n    if (!getline(cin, s)) {\\n        cout << 0 << \\"\\\\n\\";\\n        return 0;\\n    }\\n    int max_len = 0;\\n    int start = 0;\\n    vector<int> char_map(256, -1);\\n    for (int i = 0; i < (int)s.length(); i++) {\\n        unsigned char c = s[i];\\n        if (char_map[c] >= start) {\\n            start = char_map[c] + 1;\\n        }\\n        char_map[c] = i;\\n        max_len = max(max_len, i - start + 1);\\n    }\\n    cout << max_len << \\"\\\\n\\";\\n    return 0;\\n}", "java": "import java.io.*;\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        String s = br.readLine();\\n        if (s == null) {\\n            System.out.println(0);\\n            return;\\n        }\\n        int maxLen = 0;\\n        int start = 0;\\n        int[] charMap = new int[256];\\n        java.util.Arrays.fill(charMap, -1);\\n        for (int i = 0; i < s.length(); i++) {\\n            char c = s.charAt(i);\\n            if (c < 256) {\\n                if (charMap[c] >= start) {\\n                    start = charMap[c] + 1;\\n                }\\n                charMap[c] = i;\\n            }\\n            maxLen = Math.max(maxLen, i - start + 1);\\n        }\\n        System.out.println(maxLen);\\n    }\\n}", "rust": "use std::io::{self, BufRead, Write, BufWriter};\\nfn main() {\\n    let stdin = io::stdin();\\n    let stdout = io::stdout();\\n    let mut out = BufWriter::new(stdout.lock());\\n    let mut lines = stdin.lock().lines();\\n    let mut s = String::new();\\n    if let Some(Ok(line)) = lines.next() {\\n        s = line;\\n    }\\n    let mut max_len = 0;\\n    let mut start = 0;\\n    let mut char_map = vec![-1isize; 256];\\n    let bytes = s.as_bytes();\\n    for i in 0..bytes.len() {\\n        let c = bytes[i] as usize;\\n        if char_map[c] >= start {\\n            start = char_map[c] + 1;\\n        }\\n        char_map[c] = i as isize;\\n        max_len = std::cmp::max(max_len, i as isize - start + 1);\\n    }\\n    writeln!(out, \\"{}\\", max_len).unwrap();\\n}", "python": "import sys\\ndef main():\\n    s = sys.stdin.read()\\n    if s.endswith('\\\\r\\\\n'):\\n        s = s[:-2]\\n    elif s.endswith('\\\\n'):\\n        s = s[:-1]\\n    max_len = 0\\n    start = 0\\n    char_map = {}\\n    for i, c in enumerate(s):\\n        if c in char_map and char_map[c] >= start:\\n            start = char_map[c] + 1\\n        char_map[c] = i\\n        max_len = max(max_len, i - start + 1)\\n    print(max_len)\\nif __name__ == '__main__':\\n    main()"}	2026-07-03 07:10:28.219	2026-07-03 07:10:28.219
