.", "output": "4 3 5 2 6 9 7 8 1\\n6 8 2 5 7 1 4 9 3\\n1 9 7 8 3 4 5 6 2\\n8 2 6 1 9 5 3 4 7\\n3 7 4 6 8 2 9 1 5\\n9 5 1 7 4 3 6 2 8\\n5 1 9 3 2 6 8 7 4\\n2 4 8 9 5 7 1 3 6\\n7 6 3 4 1 8 2 5 9"}]	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\n\\n// Implement Sudoku solver\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    \\n    // Read 9 lines of 9 space-separated characters and solve\\n    \\n    return 0;\\n}", "java": "import java.io.*;\\nimport java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) throws Exception {\\n        // Read 9 lines of 9 space-separated characters and solve\\n    }\\n}", "rust": "use std::io::{self, BufRead};\\n\\nfn main() {\\n    let stdin = io::stdin();\\n    // Read 9 lines of 9 space-separated characters and solve\\n}", "python": "def main():\\n    # Read 9 lines of 9 space-separated characters and solve\\n    pass\\n\\nif __name__ == \\"__main__\\":\\n    main()"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nchar board[9][9];\\nbool isValid(int r, int c, char val) {\\n    for (int i = 0; i < 9; i++) {\\n        if (board[r][i] == val) return false;\\n        if (board[i][c] == val) return false;\\n        if (board[3*(r/3) + i/3][3*(c/3) + i%3] == val) return false;\\n    }\\n    return true;\\n}\\nbool solve() {\\n    for (int r = 0; r < 9; r++) {\\n        for (int c = 0; c < 9; c++) {\\n            if (board[r][c] == '.') {\\n                for (char val = '1'; val <= '9'; val++) {\\n                    if (isValid(r, c, val)) {\\n                        board[r][c] = val;\\n                        if (solve()) return true;\\n                        board[r][c] = '.';\\n                    }\\n                }\\n                return false;\\n            }\\n        }\\n    }\\n    return true;\\n}\\nint main() {\\n    for (int r = 0; r < 9; r++) {\\n        for (int c = 0; c < 9; c++) {\\n            cin >> board[r][c];\\n        }\\n    }\\n    if (solve()) {\\n        for (int r = 0; r < 9; r++) {\\n            for (int c = 0; c < 9; c++) {\\n                cout << board[r][c] << (c == 8 ? \\"\\" : \\" \\");\\n            }\\n            cout << \\"\\n\\";\\n        }\\n    }\\n    return 0;\\n}", "java": "import java.io.*;\\nimport java.util.*;\\npublic class Main {\\n    static char[][] board = new char[9][9];\\n    public static boolean isValid(int r, int c, char val) {\\n        for (int i = 0; i < 9; i++) {\\n            if (board[r][i] == val) return false;\\n            if (board[i][c] == val) return false;\\n            if (board[3*(r/3) + i/3][3*(c/3) + i%3] == val) return false;\\n        }\\n        return true;\\n    }\\n    public static boolean solve() {\\n        for (int r = 0; r < 9; r++) {\\n            for (int c = 0; c < 9; c++) {\\n                if (board[r][c] == '.') {\\n                    for (char val = '1'; val <= '9'; val++) {\\n                        if (isValid(r, c, val)) {\\n                            board[r][c] = val;\\n                            if (solve()) return true;\\n                            board[r][c] = '.';\\n                        }\\n                    }\\n                    return false;\\n                }\\n            }\\n        }\\n        return true;\\n    }\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        for (int r = 0; r < 9; r++) {\\n            String line = br.readLine();\\n            if (line == null) return;\\n            StringTokenizer st = new StringTokenizer(line);\\n            for (int c = 0; c < 9; c++) {\\n                board[r][c] = st.nextToken().charAt(0);\\n            }\\n        }\\n        if (solve()) {\\n            for (int r = 0; r < 9; r++) {\\n                for (int c = 0; c < 9; c++) {\\n                    System.out.print(board[r][c] + (c == 8 ? \\"\\" : \\" \\"));\\n                }\\n                System.out.println();\\n            }\\n        }\\n    }\\n}", "rust": "use std::io::{self, BufRead};\\nfn is_valid(board: &[[char; 9]; 9], r: usize, c: usize, val: char) -> bool {\\n    for i in 0..9 {\\n        if board[r][i] == val { return false; }\\n        if board[i][c] == val { return false; }\\n        if board[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == val { return false; }\\n    }\\n    true\\n}\\nfn solve(board: &mut [[char; 9]; 9]) -> bool {\\n    for r in 0..9 {\\n        for c in 0..9 {\\n            if board[r][c] == '.' {\\n                for val in vec!['1', '2', '3', '4', '5', '6', '7', '8', '9'] {\\n                    if is_valid(board, r, c, val) {\\n                        board[r][c] = val;\\n                        if solve(board) { return true; }\\n                        board[r][c] = '.';\\n                    }\\n                }\\n                return false;\\n            }\\n        }\\n    }\\n    true\\n}\\nfn main() {\\n    let stdin = io::stdin();\\n    let mut lines = stdin.lock().lines();\\n    let mut board = [['.'; 9]; 9];\\n    for r in 0..9 {\\n        if let Some(Ok(line)) = lines.next() {\\n            let parts: Vec<char> = line.trim().split_whitespace()\\n                .map(|x| x.chars().next().unwrap()).collect();\\n            for c in 0..9 {\\n                board[r][c] = parts[c];\\n            }\\n        }\\n    }\\n    if solve(&mut board) {\\n        for r in 0..9 {\\n            let row_str: Vec<String> = board[r].iter().map(|&x| x.to_string()).collect();\\n            println!(\\"{}\\", row_str.join(\\" \\"));\\n        }\\n    }\\n}", "python": "import sys\\ndef is_valid(board, r, c, val):\\n    for i in range(9):\\n        if board[r][i] == val: return False\\n        if board[i][c] == val: return False\\n        if board[3*(r//3) + i//3][3*(c//3) + i%3] == val: return False\\n    return True\\ndef solve(board):\\n    for r in range(9):\\n        for c in range(9):\\n            if board[r][c] == '.':\\n                for val in '123456789':\\n                    if is_valid(board, r, c, val):\\n                        board[r][c] = val\\n                        if solve(board):\\n                            return True\\n                        board[r][c] = '.'\\n                return False\\n    return True\\ndef main():\\n    input_data = sys.stdin.read().split()\\n    if not input_data:\\n        return\\n    board = []\\n    idx = 0\\n    for _ in range(9):\\n        board.append(list(input_data[idx:idx+9]))\\n        idx += 9\\n    if solve(board):\\n        for row in board:\\n            print(' '.join(row))\\nif __name__ == \\"__main__\\":\\n    main()"}	2026-07-03 07:10:28.446	2026-07-03 07:10:28.446
