= true; res.push_back(u);\\n    for (int v : adj[u]) { if (!vis[v]) dfs(v, adj, vis, res); }\\n}\\nint main() {\\n    int n, m; if (!(cin >> n >> m)) return 0;\\n    vector<vector<int>> adj(n);\\n    for (int i = 0; i < m; i++) {\\n        int u, v; cin >> u >> v;\\n        adj[u].push_back(v); adj[v].push_back(u);\\n    }\\n    for (int i = 0; i < n; i++) sort(adj[i].begin(), adj[i].end());\\n    vector<int> res; vector<bool> vis(n, false);\\n    dfs(0, adj, vis, res);\\n    for (int i = 0; i < res.size(); i++) cout << res[i] << (i + 1 == res.size() ? \\"\\" : \\" \\");\\n    cout << \\"\\\\n\\";\\n}", "java": "import java.util.*;\\npublic class Main {\\n    static void dfs(int u, List<List<Integer>> adj, boolean[] vis, List<Integer> res) {\\n        vis[u] = true; res.add(u);\\n        for (int v : adj.get(u)) { if (!vis[v]) dfs(v, adj, vis, res); }\\n    }\\n    public static void main(String[] args) {\\n        Scanner sc = new Scanner(System.in);\\n        if (!sc.hasNextInt()) return;\\n        int n = sc.nextInt(), m = sc.nextInt();\\n        List<List<Integer>> adj = new ArrayList<>();\\n        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());\\n        for (int i = 0; i < m; i++) {\\n            int u = sc.nextInt(), v = sc.nextInt();\\n            adj.get(u).add(v); adj.get(v).add(u);\\n        }\\n        for (int i = 0; i < n; i++) Collections.sort(adj.get(i));\\n        List<Integer> res = new ArrayList<>();\\n        boolean[] vis = new boolean[n];\\n        dfs(0, adj, vis, res);\\n        for (int i = 0; i < res.size(); i++) {\\n            System.out.print(res.get(i) + (i + 1 == res.size() ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n    }\\n}", "rust": "use std::io::{self, Read};\\nfn dfs(u: usize, adj: &Vec<Vec<usize>>, vis: &mut Vec<bool>, res: &mut Vec<usize>) {\\n    vis[u] = true; res.push(u);\\n    for &v in &adj[u] { if !vis[v] { dfs(v, adj, vis, res); } }\\n}\\nfn main() {\\n    let mut input = String::new();\\n    io::stdin().read_to_string(&mut input).unwrap();\\n    let mut words = input.split_whitespace();\\n    if let Some(n_str) = words.next() {\\n        let n: usize = n_str.parse().unwrap();\\n        let m: usize = words.next().unwrap().parse().unwrap();\\n        let mut adj = vec![vec![]; n];\\n        for _ in 0..m {\\n            let u: usize = words.next().unwrap().parse().unwrap();\\n            let v: usize = words.next().unwrap().parse().unwrap();\\n            adj[u].push(v); adj[v].push(u);\\n        }\\n        for i in 0..n { adj[i].sort(); }\\n        let mut res = Vec::new();\\n        let mut vis = vec![false; n];\\n        dfs(0, &adj, &mut vis, &mut res);\\n        let out: Vec<String> = res.iter().map(|x| x.to_string()).collect();\\n        println!(\\"{}\\", out.join(\\" \\"));\\n    }\\n}", "python": "import sys\\nsys.setrecursionlimit(2000)\\ndef dfs(u, adj, vis, res):\\n    vis[u] = True; res.append(u)\\n    for v in adj[u]:\\n        if not vis[v]: dfs(v, adj, vis, res)\\ndef main():\\n    data = sys.stdin.read().split()\\n    if not data: return\\n    n, m = int(data[0]), int(data[1])\\n    adj = [[] for _ in range(n)]\\n    idx = 2\\n    for _ in range(m):\\n        u, v = int(data[idx]), int(data[idx+1])\\n        adj[u].append(v); adj[v].append(u)\\n        idx += 2\\n    for i in range(n): adj[i].sort()\\n    res, vis = [], [False] * n\\n    dfs(0, adj, vis, res)\\n    print(*(res))\\nif __name__ == '__main__': main()"}	2026-07-03 07:10:28.471	2026-07-03 07:10:28.471
